    "diagramSvg": "<svg viewBox=\"0 0 559 133\" class=\"max-w-md w-full h-auto mx-auto my-2\" xmlns=\"http://www.w3.org/2000/svg\"><image href=\"data:image/png;base64,\" width=\"559\" height=\"133\"/></svg>"
